;------------------------------------------------------------------------------; Auteur..........: Daniel Lafrance, Trois-Rivières, Québec, Canada; Nom du fichier..: m-c64-utils.asm; Type fichier....: Macros; Scripteur.......: Daniel Lafrance, Québec, canada.; version.........: 0.1.0; Revision........: 20151126;                   20261101  Vérification et francisation des commentaires.;------------------------------------------------------------------------------;------------------------------------------------------------------------------; Place dans ZP1 une adresse reçu en paramètre.                            OK;------------------------------------------------------------------------------setzpage1      .macro addr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda  #<\addr         ; Charge le LSB du paramètre               sta  zpage1          ; ... le place dans $00fb.               lda  #>\addr+1       ; Charge le MSB du paramètre               sta  zpage1+1        ; ... le place dans $00fc.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Place dans ZP2 une adresse reçu en paramètre.                            OK;------------------------------------------------------------------------------setzpage2      .macro addr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda  #<\addr         ; Charge le LSB du paramètre               sta  zpage2          ; ... le place dans $00fb.               lda  #>\addr+1       ; Charge le MSB du paramètre               sta  zpage2+1        ; ... le place dans $00fc.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Place une valeur 16 bits en mémoire à l'adresse donnée en paramètre.     OK;------------------------------------------------------------------------------wordtomem      .macro mot,pointeur               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #<\mot         ; Charge le LSB de la valeur en param.               sta   \pointeur      ; ... et le place en mémoire.                                         lda   #>\mot         ; Charge le MSB de la valeur en param.               sta   \pointeur+1    ; ... et le place en mémoire.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm ;------------------------------------------------------------------------------; Charge dans $YYXX le contenu de ladresse 16 bits donnée en paramètre.    OK;------------------------------------------------------------------------------ldyxdata       .macro pointeur               php               ldy   \pointeur+1               ldx   \pointeur               plp               .endm;------------------------------------------------------------------------------; Charge dans $xxyy le contenu de ladresse 16 bits donnée en paramètre.    OK;------------------------------------------------------------------------------ldxydata       .macro pointeur               php               ldy   \pointeur               ldx   \pointeur+1               plp               .endm;------------------------------------------------------------------------------; Sauvegarde le contenu 16 bits $YYXX l'adresse donnée en paramètre.       OK;------------------------------------------------------------------------------styxdata       .macro pointeur               sty   \pointeur+1               stx   \pointeur               .endm;------------------------------------------------------------------------------; Sauvegarde le contenu 16 bits $XXYY l'adresse donnée en paramètre.       OK;------------------------------------------------------------------------------stxydata       .macro pointeur               sty   \pointeur               stx   \pointeur+1               .endm;------------------------------------------------------------------------------; Charge dans $YYXX le nombre 16 bits donnée en paramètre.                 OK;------------------------------------------------------------------------------ldyxptr        .macro immval               php               ldy   #>\immval               ldx   #<\immval               plp               .endm;------------------------------------------------------------------------------; Charge dans $XXYY le nombre 16 bits donnée en paramètre.                 OK;------------------------------------------------------------------------------ldxyptr        .macro xyimm               php               ldx   #>\xyimm               ldy   #<\xyimm               plp               .endm;------------------------------------------------------------------------------; Charge dans $AAXX le contenu de ladresse 16 bits donnée en paramètre.    OK;------------------------------------------------------------------------------ldaxdata       .macro axadd               php               lda   \axadd+1 ;msb adr dans A.               ldx   \axadd   ;lsb adr dans X.               plp               .endm;------------------------------------------------------------------------------; Charge dans $AAXX un nombre 16 bits donnée en paramètre.                 OK;------------------------------------------------------------------------------ldaxptr        .macro aximm               php               lda   #>\aximm ;MSB val dans a.               ldx   #<\aximm ;LSB val dans x.               plp               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp1data      .macro pointeur               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   \pointeur      ; Charge le LSB du pointeur               sta   zpage1         ; ... copie dans LSB de zpage1.               lda   \pointeur+1    ; Charge le MSB du pointeur               sta   zpage1+1       ; ... copie dans MSB de zpage1.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp2data      .macro pointeur               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   \pointeur      ; Charge le LSB du pointeur               sta   zpage2         ; ... copie dans LSB de zpage2.               lda   \pointeur+1    ; Charge le MSB du pointeur               sta   zpage2+1       ; ... copie dans MSB de zpage2.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp1ptr       .macro immval               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #<\immval      ;Charge le LSB du pointeur et               sta   zpage1         ; ... copie dans LSB de zpage1.               lda   #>\immval      ;Charge le MSB du pointeur et               sta   zpage1+1       ; ... copie dans MSB de zpage1.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage2 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp2ptr       .macro immval               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #<\immval      ;Charge le LSB du pointeur et               sta   zpage2         ; ... copie dans LSB de zpage2.               lda   #>\immval      ;Charge le MSB du pointeur et               sta   zpage2+1       ; ... copie dans MSB de zpage2.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Affichage d'un caractere par kernal.                                     OK;------------------------------------------------------------------------------outcar         .macro carno               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #\carno        ; Charge le code dans Acc pour               jsr   chrout         ; ... l'afficher avec $ffd2.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm        ;------------------------------------------------------------------------------; Affiche une chaine de caracteres parle kernal.                           OK;------------------------------------------------------------------------------outstr         .macro string               jsr   push           ; Sauvegarde les registres.               ldy   #>\string+1    ; Le MSB de l'adresse dans Y.               ldx   #<\string      ; Le LSB de l'adresse dans X.               jsr   putsyx         ; Affiche le texte.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine de caracteres par le kernal a la position (x,y) placée ; ... au début de la chaine.                                               OK;------------------------------------------------------------------------------outstrxy       .macro string               jsr   push           ; Sauvegarde les registres.               ldx   \string        ; Charge la colonne.               ldy   \string+1      ; Charge la ligne               jsr   gotoxy         ; Positionne le curseur.               #printyx \string+2               ;ldx   \string+2    ; Charge le LSB de l'adresse du texte.               ;ldy   #>\string+2    ; Charge le MSB de l'adresse du texte.               ;jsr   putsyx               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Deplace le curseur a la position (x,y).                                  OK;------------------------------------------------------------------------------locate         .macro x,y               jsr push               ldx #\x               ldy #\y               jsr gotoxy               jsr pop               .endm;------------------------------------------------------------------------------; Affiche une chaine dont l'adresse est passé en paramètre.                OK;------------------------------------------------------------------------------print          .macro strptr               jsr  push               ldx  #<\strptr               ldy  #>\strptr               jsr  putsyx               jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX suivie par une crlf.                OK;------------------------------------------------------------------------------println        .macro strptr               jsr  push               ldx  #<\strptr               ldy  #>\strptr               jsr  putsyx               lda  #$0d               jsr  chrout               jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y.                  OK;------------------------------------------------------------------------------print_xy       .macro x,y,strptr               jsr  push               #locate \x,\y               #print \strptr                jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y dans ka couleur C.; Le code de couleur vidéo est nécessaire.; La couleur actuelle est sauvegardée.                                     OK;------------------------------------------------------------------------------print_cxy      .macro c,x,y,strptr               jsr   push               lda   bascol               pha                lda   #\c               sta   bascol               #print_xy \x, \y,\strptr               pla               sta   bascol               jsr   pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y.; La position X,Y constitue les deux premier de la chaine.                 OK;------------------------------------------------------------------------------printxy        .macro strptr               jsr   push               ldx   #<\strptr                ldy   #>\strptr               jsr   putsxy               jsr   pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y dans la couleur C.; La couleur et position X,Y constitue les trois premier de la chaine.     OK;------------------------------------------------------------------------------printcxy       .macro strptr               jsr   push               ldx   #<\strptr                ldy   #>\strptr               jsr   putscxy               jsr   pop               .endm;------------------------------------------------------------------------------; Affiche un texte précédé d'un préfixe.                                   OK;------------------------------------------------------------------------------printfmt       .macro prefix, strptr               jsr   push               #outcar  \prefix               #print   \strptr               jsr   pop               .endm;------------------------------------------------------------------------------; Affiche un texte précédé d'un préfixe à la position X,Y.                 OK;------------------------------------------------------------------------------printfmtxy     .macro x,y,prefix,strptr               #locate \x,\y               #printfmt \prefix,\strptr               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire issue d'une case memoire.              OK;------------------------------------------------------------------------------printval16bin  .macro adresse               jsr   pushall               lda   #<\adresse               sta   $fb               lda   #>\adresse               sta   $fb+1               ldy   #$01                lda   ($fb),y               jsr   atobin               #printfmt "%", a2binstr               dey               lda   ($fb),y               jsr   atobin               #print a2binstr               jsr  popall               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire issue d'une case memoire (indirect).   OK;------------------------------------------------------------------------------printptr16bin  .macro adresse               jsr   pushall               lda   #>\adresse+1               lda   #>\adresse+1               jsr   atobin               #printfmt "%", a2binstr               lda   #<\adresse               jsr   atobin               #printfmt "", a2binstr               jsr   popall               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire issue d'une case memoire (indirect).   OK;------------------------------------------------------------------------------printwordbin   .macro adresse               jsr  pushall               lda  #<\adresse               sta  $fb               lda  #>\adresse               sta  $fb+1               ldy  #$01                lda  ($fb),y               jsr  atobin               #printfmt "%", a2binstr               dey               lda  ($fb),y               jsr  atobin               #print a2binstr               jsr  popall               .endm;------------------------------------------------------------------------------; Place sur la pile tous les registres.                                    OK;------------------------------------------------------------------------------mpushr         .macro               php               pha               txa               pha               tya               pha               .endm;------------------------------------------------------------------------------; Recupere les registres de la pile.                                       OK;------------------------------------------------------------------------------mpopr          .macro               pla               tay               pla               tax               pla               plp               .endm        ;------------------------------------------------------------------------------; Initialise les donneed de la fonction loop.                              OK;------------------------------------------------------------------------------setloop        .macro lcount               pha               lda  #<\lcount               sta  loopcount               lda  #>\lcount               sta  loopcount+1               pla               .endm;------------------------------------------------------------------------------; Permet les changement de police avec [C=]+[SHIFT].                       OK;------------------------------------------------------------------------------enable         .macro               php               pha               lda   #$09               jsr   $ffd2               pla               plp               .endm;------------------------------------------------------------------------------; Inhibe les changement de police avec [C=]+[SHIFT].                       OK;------------------------------------------------------------------------------disable        .macro               php               pha               lda   #$08               jsr   $ffd2               pla               plp               .endm;------------------------------------------------------------------------------; Selectionne le jeu de caracteres minuscule.                              OK;------------------------------------------------------------------------------tolower        .macro               php               pha               lda   #14               jsr   $ffd2               pla               plp               .endm;------------------------------------------------------------------------------; Selectionne le jeu de caracteres majuscule.                              OK;------------------------------------------------------------------------------toupper        .macro               php               pha               lda   #b_uppercase               jsr   $ffd2               pla               plp               .endm;------------------------------------------------------------------------------; Change la couleur de la bordure.                                         OK;------------------------------------------------------------------------------changebord     .macro c               php               pha               lda   #\c               sta   $d020               pla               plp               .endm;------------------------------------------------------------------------------; Change la couleur de l'arriere plan de l'ecran.                          OK;------------------------------------------------------------------------------changeback     .macro c               php               pha               lda  #\c               sta  $d021               pla               plp               .endm;------------------------------------------------------------------------------; Sélectionne mes couleurs préférées.                                      OK;------------------------------------------------------------------------------mescol         .macro               jsr  push               #changebord cvert               #changeback cbleu               #color cblanc               jsr  pop               .endm;------------------------------------------------------------------------------; Couleurs Commodore 64 + texte blanc.                                     OK;------------------------------------------------------------------------------c64col         .macro               jsr  push               #changebord cbleupale               #changeback cbleu               #color cblanc               jsr  pop               .endm;------------------------------------------------------------------------------; Sélectionne les couleurs naturelle du commodore Vic 20.                  OK;------------------------------------------------------------------------------v20col         .macro               jsr  push               #changebord ccyan               #changeback cblanc               #color cbleu               jsr  pop               .endm;------------------------------------------------------------------------------; Sélectionne un jeu de couleurs grises.                                   OK;------------------------------------------------------------------------------griscol        .macro               jsr  push               #changebord cgrismoyen               #changeback cgrisfonce               #color cgrispale               jsr  pop               .endm;------------------------------------------------------------------------------; Sélectionne las couleurs du fond, de la bordure et du texte.             OK;------------------------------------------------------------------------------scrcolors      .macro fg, bg                        pha               lda #(\bg*16+(\fg|8))               sta  vicscrbrd               pla               .endm;------------------------------------------------------------------------------; Sélectionne la couleur du texte.                                         OK;------------------------------------------------------------------------------color          .macro    col               pha               lda  #\col               sta  bascol               pla               .endm;------------------------------------------------------------------------------